        System.Text.StringBuilder t1 = emon.Testport.NewText();
        System.Text.StringBuilder t2 = emon.Testport.NewText();
        // Front matter in roman numerals (centred), the body in arabic: the label is the number AS PRINTED.
        FlPages(wd, ln, et, 6);
