    [Xunit.Fact]
    public static void TestARunningTitleTheBodyAlreadySaysIsDroppedAndTheRestIsKept() {
        emon.Port.Cells wd = emon.Port.NewCells();
        emon.Port.Cells ln = emon.Port.NewCells();
        emon.Port.Cells et = emon.Port.NewCells();
        emon.Port.Cells txt = emon.Port.NewCells();
        emon.Port.Cells md = emon.Port.NewCells();
        emon.Port.Cells lb = emon.Port.NewCells();
        System.Text.StringBuilder t1 = emon.Testport.NewText();
        System.Text.StringBuilder t2 = emon.Testport.NewText();
        System.Text.StringBuilder t3 = emon.Testport.NewText();
        // Page 1 has the title as a heading; every page repeats it in the top margin, with `Page N of M` at the foot.
        FlPages(wd, ln, et, 3);
        FlLine(wd, ln, et, emon.Testport.TextBlob("Annual Report"), 1, 7200, 9000, 30000, 10000, 0, 1800);
        FlTop(wd, ln, et, emon.Testport.TextBlob("Annual Report"), 1, 28000, 33000);
        FlTop(wd, ln, et, emon.Testport.TextBlob("Annual Report"), 2, 28000, 33000);
        FlTop(wd, ln, et, emon.Testport.TextBlob("Annual Report"), 3, 28000, 33000);
        emon.Testport.AssertEq(FlRun(wd, ln, et, 3, 0, 0, txt, md, lb, t1), 0, "title: well formed");
        emon.Testport.AssertText(t1, "Dr@1:Annual Report;Dr@2:Annual Report;Dr@3:Annual Report;P:Annual Report;P:alpha beta. |alpha beta. |alpha beta.;", "a running title that is one line of the body is the output saying it twice: dropped, in the ledger");
        // A company name that the body does not say is information: ONE furniture root for all the pages.
        FlClear(wd, ln, et);
        FlPages(wd, ln, et, 3);
        FlTop(wd, ln, et, emon.Testport.TextBlob("ACME Corporation"), 1, 28000, 33000);
        FlTop(wd, ln, et, emon.Testport.TextBlob("ACME Corporation"), 2, 28000, 33000);
        FlTop(wd, ln, et, emon.Testport.TextBlob("ACME Corporation"), 3, 28000, 33000);
        emon.Testport.AssertEq(FlRun(wd, ln, et, 3, 0, 0, txt, md, lb, t2), 0, "company: well formed");
        emon.Testport.AssertText(t2, "Fh1,2,3:ACME Corporation;P:alpha beta. |alpha beta. |alpha beta.;", "kept once, with the pages it was on");
        // `drop` takes it out too, and says so.
        emon.Testport.AssertEq(FlRun(wd, ln, et, 3, 0, 2, txt, md, lb, t3), 0, "company drop: well formed");
        emon.Testport.AssertText(t3, "Dr@1:ACME Corporation;Dr@2:ACME Corporation;Dr@3:ACME Corporation;P:alpha beta. |alpha beta. |alpha beta.;", "drop: nothing kept, everything in the ledger");
    }
