    [Xunit.Fact]
    public static void TestALineSeenOnOnePageIsNotFurniture() {
        emon.Port.Cells wd = emon.Port.NewCells();
        emon.Port.Cells ln = emon.Port.NewCells();
        emon.Port.Cells et = emon.Port.NewCells();
        emon.Port.Cells txt = emon.Port.NewCells();
        emon.Port.Cells md = emon.Port.NewCells();
        emon.Port.Cells lb = emon.Port.NewCells();
        System.Text.StringBuilder t1 = emon.Testport.NewText();
        System.Text.StringBuilder t2 = emon.Testport.NewText();
        // A single page has no recurrence to find: a line in the margin of a SIXTEEN-page document that is on one page only is
        // left in the flow.
        FlPages(wd, ln, et, 16);
        FlTop(wd, ln, et, emon.Testport.TextBlob("Draft for review"), 5, 7200, 30000);
        emon.Testport.AssertEq(FlRun(wd, ln, et, 16, 0, 0, txt, md, lb, t1), 0, "once: well formed");
        // (A one-line page's line fills its fragment, so P4.1 continues the paragraph over the page break: `|`.)
        emon.Testport.AssertText(t1, "P:alpha beta. |alpha beta. |alpha beta. |alpha beta.;P:Draft for review;P:alpha beta. |alpha beta. |alpha beta. |alpha beta. |alpha beta. |alpha beta. |alpha beta. |alpha beta. |alpha beta. |alpha beta. |alpha beta. |alpha beta.;", "a line on one page of sixteen stays in the flow");
        // On two pages of sixteen it is still not enough (30 per cent of the pages are needed).
        FlClear(wd, ln, et);
        FlPages(wd, ln, et, 16);
        FlTop(wd, ln, et, emon.Testport.TextBlob("Draft for review"), 5, 7200, 30000);
        FlTop(wd, ln, et, emon.Testport.TextBlob("Draft for review"), 9, 7200, 30000);
        emon.Testport.AssertEq(FlRun(wd, ln, et, 16, 0, 0, txt, md, lb, t2), 0, "twice: well formed");
        emon.Testport.AssertText(t2, "P:alpha beta. |alpha beta. |alpha beta. |alpha beta.;P:Draft for review;P:alpha beta. |alpha beta. |alpha beta. |alpha beta.;P:Draft for review;P:alpha beta. |alpha beta. |alpha beta. |alpha beta. |alpha beta. |alpha beta. |alpha beta. |alpha beta.;", "on two pages of sixteen it is still not enough");
    }
