    [Xunit.Fact]
    public static void TestPageLabelsOfTheCatalogueWinOverThePrintedNumbers() {
        emon.Port.Cells wd = emon.Port.NewCells();
        emon.Port.Cells ln = emon.Port.NewCells();
        emon.Port.Cells et = emon.Port.NewCells();
        emon.Port.Cells txt = emon.Port.NewCells();
        emon.Port.Cells md = emon.Port.NewCells();
        emon.Port.Cells lb = emon.Port.NewCells();
        System.Text.StringBuilder t1 = emon.Testport.NewText();
        int i = 0;
        // Two pages numbered 5 and 6 at the foot, and a catalogue that says lower roman from page 0 (ii at page 2): the labels
        // are the catalogue's, the printed numbers are still taken out of the flow.
        FlPages(wd, ln, et, 2);
        FlBottom(wd, ln, et, emon.Testport.TextBlob("5"), 1, 30000, 31000);
        FlBottom(wd, ln, et, emon.Testport.TextBlob("6"), 2, 30000, 31000);
        while (i < 60) {
            emon.Port.CellsPush(md, 0);
            i += 1;
        }
        emon.Port.CellsSet(md, 54, 1);
        // one range: first page 0, style r (3), no prefix, number 1 on the first page, 1 + the pages after the last, no bits
        emon.Port.CellsPush(lb, 0);
        emon.Port.CellsPush(lb, 3);
        emon.Port.CellsPush(lb, -1);
        emon.Port.CellsPush(lb, 0);
        emon.Port.CellsPush(lb, 1);
        emon.Port.CellsPush(lb, 2);
        emon.Port.CellsPush(lb, 0);
        emon.Port.CellsPush(lb, 0);
        emon.Testport.AssertEq(FlRun(wd, ln, et, 2, 0, 0, txt, md, lb, t1), 0, "labels: well formed");
        emon.Testport.AssertText(t1, "L1=i;L2=ii;Dp@1:5;Dp@2:6;P:alpha beta. |alpha beta.;", "the catalogue's labels, the printed numbers dropped");
    }
    internal static int FlFile(byte[] blob, int mode, System.Text.StringBuilder t) {
        // A real file through the whole pipeline as the Engine runs it, and the brief of the Model. Answers 0, or the open
        // status, or -1.
        emon.Port.Cells ar = emon.Port.NewCells();
        emon.Port.Cells dc = emon.Port.NewCells();
        emon.Port.Cells a = emon.Port.NewCells();
        emon.Port.Cells b = emon.Port.NewCells();
        emon.Port.Cells st = emon.Port.NewCells();
        emon.Port.Cells pg = emon.Port.NewCells();
        emon.Port.Cells idx = emon.Port.NewCells();
        emon.Port.Cells txt = emon.Port.NewCells();
        emon.Port.Cells w = emon.Port.NewCells();
        emon.Port.Cells seen = emon.Port.NewCells();
        emon.Port.Cells md = emon.Port.NewCells();
        emon.Port.Cells xm = emon.Port.NewCells();
        emon.Port.Cells ol = emon.Port.NewCells();
        emon.Port.Cells lb = emon.Port.NewCells();
        emon.Port.Cells nd = emon.Port.NewCells();
        emon.Port.Cells nt = emon.Port.NewCells();
        emon.Port.Cells cx = emon.Port.NewCells();
        emon.Port.Cells ox = emon.Port.NewCells();
        emon.Port.Cells cs = emon.Port.NewCells();
        emon.Port.Cells @out = emon.Port.NewCells();
        emon.Port.Cells f0 = emon.Port.NewCells();
        emon.Port.Cells f1 = emon.Port.NewCells();
        emon.Port.Cells f2 = emon.Port.NewCells();
        emon.Port.Cells f3 = emon.Port.NewCells();
        emon.Port.Cells gl = emon.Port.NewCells();
        emon.Port.Cells et = emon.Port.NewCells();
        emon.Port.Cells mk = emon.Port.NewCells();
        emon.Port.Cells fnt = emon.Port.NewCells();
        emon.Port.Cells wd = emon.Port.NewCells();
        emon.Port.Cells ln = emon.Port.NewCells();
        emon.Port.Cells ss = emon.Port.NewCells();
        emon.Port.Cells se = emon.Port.NewCells();
        emon.Port.Cells sk = emon.Port.NewCells();
        emon.Port.Cells sc = emon.Port.NewCells();
        emon.Port.Cells so = emon.Port.NewCells();
        emon.Port.Cells sa = emon.Port.NewCells();
        emon.Port.Cells wk = emon.Port.NewCells();
        emon.Port.Cells ha = emon.Port.NewCells();
        emon.Port.Cells hb = emon.Port.NewCells();
        emon.Port.Cells hh = emon.Port.NewCells();
        emon.Port.Cells nodes = emon.Port.NewCells();
        emon.Port.Cells attrs = emon.Port.NewCells();
        emon.Port.Cells regions = emon.Port.NewCells();
        emon.Port.Cells text = emon.Port.NewCells();
        emon.Port.Cells pages = emon.Port.NewCells();
        emon.Port.Cells ledger = emon.Port.NewCells();
        emon.Port.Cells layout = emon.Port.NewCells();
        emon.Port.Cells ord = emon.Port.NewCells();
        emon.Port.Cells raw = emon.Port.NewCells();
        emon.Port.Cells tmp = emon.Port.NewCells();
        emon.Port.Cells fr = emon.Port.NewCells();
        emon.Port.Cells gp = emon.Port.NewCells();
        emon.Port.Cells cd = emon.Port.NewCells();
        emon.Port.Cells sl = emon.Port.NewCells();
        emon.Port.Cells gr = emon.Port.NewCells();
        emon.Port.Cells ford = emon.Port.NewCells();
        emon.Port.Cells tx = emon.Port.NewCells();
        emon.Port.Cells bh = emon.Port.NewCells();
        emon.Port.Cells fo = emon.Port.NewCells();
        emon.Port.Cells fp = emon.Port.NewCells();
        emon.Port.Cells ft = emon.Port.NewCells();
        emon.Port.Cells pl = emon.Port.NewCells();
        emon.Port.Cells chk = emon.Port.NewCells();
        emon.Port.Cells pa = emon.Port.NewCells();
        emon.Port.Cells im = emon.Port.NewCells();
        emon.Port.Cells pts = emon.Port.NewCells();
        emon.Port.Cells gx = emon.Port.NewCells();
        emon.Port.Src pdf = emon.Port.SrcOfBlob(blob);
        int status = 0;
        int r = 0;
        int np = 0;
        status = Pdfdoc.PdOpen(pdf, ar, dc, a, b, st);
        if (status != 0) {
            return status;
        }
        r = Pdfcontent.PcDocument(pdf, ar, dc, a, b, st, cx, ox, cs, @out, f0, f1, f2, f3, gl, et, mk, fnt, pg, wd, ln, pa, im, pts, gx);
        if (r != 0) {
            return -1;
        }
        np = Pdfdoc.PdPgCount(pg);
        Pdfx.PxIndexBuild(pdf, ar, dc, a, b, st, pg, idx);
        r = Pdfmeta.PmRun(pdf, ar, dc, a, b, st, pg, idx, txt, w, seen, md, xm, ol, lb, nd, nt);
        if (r < 0) {
            return -1;
        }
        r = Pdfstruct.TgRead(pdf, ar, dc, a, b, st, pg, idx, txt, w, seen, ss, se, sk, sc, so, wk, md);
        if (r < 0) {
            return -1;
        }
        r = Pdfstruct.TgJoin(ss, se, sk, sc, so, sa, gl, mk, fnt, pg, ha, hb, hh);
        Model.ModelInit(nodes, attrs, regions, text, pages, ledger, layout);
        Para.PaPages(pg, pages);
        Furniture.FuFind(wd, ln, et, gl, mk, pages, np, txt, md, lb, Pdfstruct.TgTrust(ss), mode, cd, sl, gr, ford, tx, bh, fo, fp, ft, pl);
        FlBuild(wd, ln, et, np, pages, layout, nodes, attrs, regions, text, ord, raw, tmp, fr, gp);
        Furniture.FuWrite(fo, fp, ft, pl, np, nodes, attrs, regions, text, pages, ledger, tmp);
        FlBrief(t, nodes, attrs, text, pages, ledger, 0);
        r = Model.ModelCheck(nodes, attrs, regions, text, pages, ledger, layout, chk);
        return r;
    }
    [Xunit.Fact]
    public static void TestTheTaggedFixturesLoseTheirRunningHeaderFooterAndWatermark() {
        // `good.pdf` is tagged (its running header, footer and DRAFT watermark are /Artifact marked content: the tree is trusted);
        // `bad.pdf` says the same page wrongly (the running header is tagged P, a heading is marked Footer): the geometry and the
        // repetition still find the furniture, whatever the tree says (D034, D076). Each page has `Page N` and `Quarterly Report`.
        System.Text.StringBuilder t1 = emon.Testport.NewText();
        System.Text.StringBuilder t2 = emon.Testport.NewText();
        System.Text.StringBuilder t3 = emon.Testport.NewText();
        emon.Testport.AssertEq(FlFile(emon.Testport.TestFile("pdf/tagged/good.pdf"), 0, t1), 0, "good: well formed");
        emon.Testport.AssertText(t1, "L1=1;L2=2;Dr@1:Quarterly Report;Dr@2:Quarterly Report;Dp@1:Page 1;Dp@2:Page 2;Dw@1:DRAFT;", "good: header, footer, watermark out, the content as it was");
        emon.Testport.AssertEq(FlFile(emon.Testport.TestFile("pdf/tagged/bad.pdf"), 0, t2), 0, "bad: well formed");
        emon.Testport.AssertText(t2, "L1=1;L2=2;Dr@1:Quarterly Report;Dr@2:Quarterly Report;Dp@1:Page 1;Dp@2:Page 2;Dw@1:DRAFT;", "bad: the same page told wrongly by the tree is cleaned up the same way (D034: verified, not obeyed)");
        emon.Testport.AssertEq(FlFile(emon.Testport.TestFile("pdf/tagged/good.pdf"), 1, t3), 0, "good, keep: well formed");
        emon.Testport.AssertText(t3, "", "keep: nothing leaves the flow, and nothing is said");
    }
